# cluster cells per fill into connected rectangles
from collections import deque
def clusters(cells):
    cells=set(cells); seen=set(); out=[]
    for p in cells:
        if p in seen: continue
        q=deque([p]); comp=[]
        seen.add(p)
        while q:
            r,c=q.popleft(); comp.append((r,c))
            for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                n=(r+dr,c+dc)
                if n in cells and n not in seen:
                    seen.add(n); q.append(n)
        out.append(comp)
    return out
